previewCss:
.darma-loader-darma-b14-pancake-flip { --accent: var(--loader-color, #d97706); --accent-2: var(--loader-secondary-color, #fcd34d); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .72); position: relative; }
.darma-loader-darma-b14-pancake-flip .darma-loader-darma-b14-pancake-flip__pan { position: absolute; bottom: 12%; left: 4%; width: 62%; height: 15%; border-radius: 4px 4px 46% 46%; background: linear-gradient(#475569, #1e293b); animation: darma-loader-darma-b14-pancake-flip-toss calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b14-pancake-flip .darma-loader-darma-b14-pancake-flip__pan::after { content: ''; position: absolute; left: 97%; top: 24%; width: 46%; height: 30%; border-radius: 0 4px 4px 0; background: #334155; }
.darma-loader-darma-b14-pancake-flip span { position: absolute; bottom: 26%; left: 14%; width: 42%; height: 11%; border-radius: 50%; background: radial-gradient(ellipse at 50% 36%, color-mix(in srgb, #fff 26%, var(--accent-2)), var(--accent)); animation: darma-loader-darma-b14-pancake-flip-flip-cake calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-pancake-flip-toss { 0%, 18% { transform: translateY(0) rotate(0deg); } 28% { transform: translateY(-16%) rotate(-8deg); } 44%, 100% { transform: translateY(0) rotate(0deg); } }
@keyframes darma-loader-darma-b14-pancake-flip-flip-cake { 0%, 14% { transform: translateY(0) rotate(0deg) scaleY(1); } 40% { transform: translateY(-186%) rotate(180deg) scaleY(.78); } 62% { transform: translateY(-42%) rotate(338deg) scaleY(1); } 72% { transform: translateY(0) rotate(360deg) scaleY(.68); } 82%, 100% { transform: translateY(0) rotate(360deg) scaleY(1); } }

